/**
 * 运行时 map JSON 清洗：剥离重复接取/交任务页，修正无效的 appear event_done 引用。
 */
import { isBattleEnemyNpcUid, type StoryEventLike } from './story-event-page-resolver';

export type SanitizeStoryMapReport = {
  duplicatePagesRemoved: number;
  appearRefsFixed: number;
  trailingDialogReqsFixed: number;
  sequentialReqsInjected: number;
};

function eventHasTaskAccept(ev: StoryEventLike): boolean {
  return Boolean(ev.server?.effects?.some((e) => (e as { action?: string }).action === 'task_accept'));
}

function eventHasTaskComplete(ev: StoryEventLike): boolean {
  return Boolean(ev.server?.effects?.some((e) => (e as { action?: string }).action === 'task_complete'));
}

function eventDoneCount(reqs: unknown[]): number {
  return reqs.filter((r) => {
    const t = (r as { type?: string }).type ?? '';
    return t === 'event_done' || t === 'event_completed';
  }).length;
}

function hasEventDoneFor(reqs: unknown[], eventId: string): boolean {
  return reqs.some((r) => {
    const x = r as { type?: string; eventId?: string };
    const t = x.type ?? '';
    return (t === 'event_done' || t === 'event_completed') && x.eventId === eventId;
  });
}

function shouldSkipSequentialInject(ev: StoryEventLike): boolean {
  const reqs = ev.server?.requirements ?? [];
  const edCount = eventDoneCount(reqs);
  if (edCount >= 2) return true;
  if (eventHasTaskComplete(ev) && edCount >= 1) return true;
  return false;
}

/** 为线性链补「上一步 event_done」，避免多页空 requirements 时跳页 */
export function injectSequentialEventRequirements(events: StoryEventLike[]): number {
  const list = events ?? [];
  if (list.length < 2) return 0;
  const sorted = [...list].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  let fixed = 0;
  let prevId: string | null = null;
  for (const ev of sorted) {
    const curId = ev.eventId ?? null;
    if (!prevId) {
      prevId = curId;
      continue;
    }
    if (!shouldSkipSequentialInject(ev)) {
      const reqs = [...(ev.server?.requirements ?? [])];
      if (!hasEventDoneFor(reqs, prevId)) {
        ev.server = ev.server ?? {};
        ev.server.requirements = [{ type: 'event_done', eventId: prevId }, ...reqs];
        fixed += 1;
      }
    }
    if (curId) prevId = curId;
  }
  return fixed;
}

function resolveTurnInEventId(events: StoryEventLike[]): string | null {
  const turnIns = events.filter((e) => eventHasTaskComplete(e));
  if (!turnIns.length) return null;
  return (
    [...turnIns].sort((a, b) => {
      const ca = (a.server?.requirements ?? []).filter(
        (r) => (r as { type?: string }).type === 'event_done',
      ).length;
      const cb = (b.server?.requirements ?? []).filter(
        (r) => (r as { type?: string }).type === 'event_done',
      ).length;
      return cb - ca;
    })[0]?.eventId ?? null
  );
}

function chainIndex(uid: string): number | null {
  const m = uid.match(/chain_(\d+)/);
  return m ? Number(m[1]) : null;
}

export function stripDuplicateGiverEventPages(events: StoryEventLike[] | null | undefined): StoryEventLike[] {
  const list = events ?? [];
  if (list.length < 2) return list;
  const sorted = [...list].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  const firstAccept = sorted.find((e) => eventHasTaskAccept(e));
  const turnIns = sorted.filter((e) => eventHasTaskComplete(e));
  const canonicalTurnIn =
    turnIns.length > 0
      ? [...turnIns].sort((a, b) => {
          const ca = (a.server?.requirements ?? []).filter(
            (r) => (r as { type?: string }).type === 'event_done',
          ).length;
          const cb = (b.server?.requirements ?? []).filter(
            (r) => (r as { type?: string }).type === 'event_done',
          ).length;
          return cb - ca;
        })[0]
      : null;

  const drop = new Set<string>();
  if (firstAccept?.eventId) {
    for (const e of sorted) {
      if (e.eventId === firstAccept.eventId) continue;
      if (eventHasTaskAccept(e) && e.eventId) drop.add(e.eventId);
    }
  }
  if (canonicalTurnIn?.eventId) {
    for (const e of turnIns) {
      if (e.eventId && e.eventId !== canonicalTurnIn.eventId) drop.add(e.eventId);
    }
  }
  if (!drop.size) return list;
  return list.filter((e) => !e.eventId || !drop.has(e.eventId));
}

function patchTrailingDialogRequirements(events: StoryEventLike[]): number {
  const sorted = [...events].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  const turnInId = resolveTurnInEventId(sorted);
  if (!turnInId) return 0;
  const turnInOrder = sorted.find((e) => e.eventId === turnInId)?.order ?? 0;
  let fixed = 0;
  for (const ev of sorted) {
    if (ev.eventType !== 'dialog') continue;
    if (ev.server?.requirements?.length) continue;
    if ((ev.order ?? 0) <= turnInOrder) continue;
    ev.server = ev.server ?? {};
    ev.server.requirements = [{ type: 'event_done', eventId: turnInId }];
    fixed += 1;
  }
  return fixed;
}

export function sanitizeStoryNpcRows(
  npcs: Array<{
    npcUid?: string;
    events?: StoryEventLike[];
    appear?: { requirements?: Array<{ type?: string; eventId?: string }> };
  }>,
): SanitizeStoryMapReport {
  const report: SanitizeStoryMapReport = {
    duplicatePagesRemoved: 0,
    appearRefsFixed: 0,
    trailingDialogReqsFixed: 0,
    sequentialReqsInjected: 0,
  };
  const knownEventIds = new Set<string>();

  for (const npc of npcs) {
    const uid = npc.npcUid ?? '';
    if (!uid || isBattleEnemyNpcUid(uid)) continue;
    const before = npc.events?.length ?? 0;
    let events = stripDuplicateGiverEventPages(npc.events);
    report.sequentialReqsInjected += injectSequentialEventRequirements(events);
    report.trailingDialogReqsFixed += patchTrailingDialogRequirements(events);
    if (events.length < before) {
      report.duplicatePagesRemoved += before - events.length;
    }
    npc.events = events;
  }

  for (const npc of npcs) {
    for (const ev of npc.events ?? []) {
      if (ev.eventId) knownEventIds.add(ev.eventId);
    }
  }

  for (const npc of npcs) {
    const reqs = npc.appear?.requirements;
    if (!reqs?.length || !npc.npcUid) continue;
    const idx = chainIndex(npc.npcUid);
    if (!idx || idx <= 1) continue;
    const prev = npcs.find(
      (n) => n.npcUid?.includes(`chain_${idx - 1}`) && !isBattleEnemyNpcUid(n.npcUid ?? ''),
    );
    const fallback = prev ? resolveTurnInEventId(prev.events ?? []) : null;
    if (!fallback) continue;
    for (const req of reqs) {
      if (req.type !== 'event_done' || !req.eventId) continue;
      if (knownEventIds.has(req.eventId)) continue;
      req.eventId = fallback;
      report.appearRefsFixed += 1;
      knownEventIds.add(fallback);
    }
  }
  return report;
}
